INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('06728876-faa0-5e47-a08e-16373f3aa11c', 'e0030000-0000-4000-8000-000000000103', 'published', 'Wóz 13', 'PL', 13, NULL, 'Całoroczny wóz z pustym wnętrzem do wykończenia: wnętrze 13 m² oraz mały zadaszony taras 4,5 m². Elewacja jest ze świerku skandynawskiego, dach z aluminiowej blachy na rąbek stojący, elementy metalowe malowane proszkowo, a wnętrze obite boazerią ze świerku skandynawskiego. Wóz jest ocieplony, a instalacja elektryczna wykonana zgodnie z obowiązującymi normami. Wykończenie wnętrza na życzenie klienta jest możliwe za dodatkową opłatą. Cena jest podana w euro, netto, bez transportu.', 'surowy-zamkniety', 4, 4, NULL, NULL, NULL, NULL, 2, 'mobilny', NULL, NULL, NULL, 1, NULL, 'Dach z aluminiowej blachy na rąbek stojący', 'Elewacja ze świerku skandynawskiego, wnętrze obite boazerią ze świerku, dach z aluminiowej blachy na rąbek stojący, całość ocieplona.', NULL, 'Wykończenie wnętrza na życzenie klienta za dodatkową opłatą, producent jest otwarty na propozycje.', 'EUR', NULL, NULL, false, '2026-10-30T19:37:09.145Z'::timestamptz, '2026-10-30T19:37:09.221Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Brak danych w ofercie producenta.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"inne","heatTransferCoefficients":"nieznana","constructionTechnologyOther":"Brak danych w ofercie producenta."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"woz-13-room-0","name":"Puste wnętrze do wykończenia","areaM2":13,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'woz-13', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('22a6f310-58d0-4ca9-a575-b7de735bbba6', '06728876-faa0-5e47-a08e-16373f3aa11c', 'en', 'Wóz 13', 'A year-round wagon with an empty interior ready to be finished: 13 m² inside plus a small 4.5 m² covered terrace. The facade is Scandinavian spruce, the roof is aluminium standing-seam sheet metal, metal parts are powder-coated, and the interior is lined with Scandinavian spruce panelling. The wagon is insulated, and the electrical installation is made to current standards. Finishing the interior to the client''s wishes is possible for an additional fee. The price is given in euro, net, excluding transport.', '2026-10-30T19:37:09.145Z'::timestamptz, '2026-10-30T19:37:09.145Z'::timestamptz, '[{"id":"woz-13-room-0","name":"Empty interior to be finished"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Scandinavian spruce facade, interior lined with spruce panelling, aluminium standing-seam roof, fully insulated.', 'Roof of aluminium standing-seam sheet metal', 'Finishing the interior to the client''s wishes for an additional fee; the producer is open to proposals.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('bff626a1-298b-4fc3-910a-c743ce7358f8', '06728876-faa0-5e47-a08e-16373f3aa11c', 'de', 'Wóz 13', 'Ein ganzjährig nutzbarer Wagen mit leerem Innenraum zum Ausbauen: 13 m² Innenfläche plus eine kleine überdachte Terrasse von 4,5 m². Die Fassade besteht aus skandinavischer Fichte, das Dach aus Aluminium-Stehfalzblech, Metallteile sind pulverbeschichtet, und der Innenraum ist mit Profilholz aus skandinavischer Fichte verkleidet. Der Wagen ist gedämmt, die Elektroinstallation ist nach geltenden Normen ausgeführt. Ein Ausbau des Innenraums nach Kundenwunsch ist gegen Aufpreis möglich. Der Preis ist in Euro angegeben, netto, ohne Transport.', '2026-10-30T19:37:09.145Z'::timestamptz, '2026-10-30T19:37:09.145Z'::timestamptz, '[{"id":"woz-13-room-0","name":"Leerer Innenraum zum Ausbauen"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Fassade aus skandinavischer Fichte, Innenraum mit Fichtenprofilholz verkleidet, Dach aus Aluminium-Stehfalzblech, vollständig gedämmt.', 'Dach aus Aluminium-Stehfalzblech', 'Ausbau des Innenraums nach Kundenwunsch gegen Aufpreis, der Hersteller ist für Vorschläge offen.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('11164f93-e48d-49f7-8cbc-4f556b2f43b1', '06728876-faa0-5e47-a08e-16373f3aa11c', 'nl', 'Wóz 13', 'Een jaarrond bruikbare woonwagen met een leeg interieur om af te werken: 13 m² binnenruimte plus een klein overdekt terras van 4,5 m². De gevel is van Scandinavisch vurenhout, het dak van aluminium liggende felsplaat, metalen onderdelen zijn poedergecoat en het interieur is bekleed met Scandinavisch vurenhout. De woonwagen is geïsoleerd en de elektrische installatie is volgens de geldende normen uitgevoerd. Afwerking van het interieur naar wens van de klant is mogelijk tegen meerprijs. De prijs is in euro, netto, exclusief transport.', '2026-10-30T19:37:09.145Z'::timestamptz, '2026-10-30T19:37:09.145Z'::timestamptz, '[{"id":"woz-13-room-0","name":"Leeg interieur om af te werken"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Gevel van Scandinavisch vurenhout, interieur bekleed met vurenhout, dak van aluminium liggende felsplaat, volledig geïsoleerd.', 'Dak van aluminium liggende felsplaat', 'Afwerking van het interieur naar wens van de klant tegen meerprijs; de producent staat open voor voorstellen.', NULL) ON CONFLICT DO NOTHING;
